async fn case(name: &str) -> Result<()> {
    let fixture = TestDatabase::memory()?;
    let name = name.to_owned();
    fixture.stores.transaction(move |tx| {
        let oracle: Value = serde_json::from_str(ORACLE)?;
        let store = EventStore::new();
        let mut sequence = 0;
        for row in oracle["oracle"].as_array().expect("oracle") .iter().filter(|row| row["name"] == name) {
            let mut detail: Value = serde_json::from_str(include_str!("../../../../fixtures/samples/PullRequestDetail.jsonl").lines().next().expect("detail"))?;
            detail.as_object_mut().expect("object").shift_remove("headSha");
            detail.as_object_mut().expect("object").extend(row["detail"].as_object().expect("detail object").clone());
            let watch = serde_json::from_value(row["watch"].clone())?;
            let remarks: Option<Vec<PullRequestComment>> = serde_json::from_value(row["remarks"].clone())?;
            let report = evaluate_pull_request_watch(&watch, &serde_json::from_value(detail)?, remarks.as_deref(), &serde_json::from_value(row["now"].clone())?)?;
            assert_eq!(serde_json::to_value(&report)?, row["expected"], "{name}, input {}", row);
            let mut thread: Value = serde_json::from_str(include_str!("../../../../fixtures/samples/OrchestrationV2AppThread.jsonl").lines().next().expect("thread"))?;
            thread["id"] = json!("thread:watch");
            thread["pullRequests"] = json!([{"host":"github.com","repository":"o/r","number":1,"url":"https://github.com/o/r/pull/1","source":"manual","linkedAt":TEST_TIME,"snapshot":null,"stack":null,"watch":report.next}]);
            let event: OrchestrationV2DomainEvent = serde_json::from_value(json!({"id":format!("watch:{sequence}"),"type":"thread.metadata-updated","threadId":"thread:watch","occurredAt":TEST_TIME,"payload":thread}))?;
            store.append(tx, None, &[event])?;
            sequence += 1;
        }
        assert!(sequence > 0);
        let events = store.read(tx, &EventFilter::default())?;
        assert_eq!(events.len(), sequence);
        for (event, row) in events.iter().zip(oracle["oracle"].as_array().expect("oracle").iter().filter(|row| row["name"] == name)) {
            let value = serde_json::to_value(event)?;
            assert_eq!(value["event"]["payload"]["pullRequests"][0]["watch"], row["expected"]["next"]);
        }
        Ok(())
    }).await
}

